fn init() -> Model = Model { a: 0, b: 0 }

fn update(m: Model, msg: Msg) -> Model = match msg {
  MoreA => m with { a: m.a + 1 }
  LessA => if m.a > 0 { m with { a: m.a - 1 } } else { m }
  MoreB => m with { b: m.b + 1 }
  LessB => if m.b > 0 { m with { b: m.b - 1 } } else { m }
}

